mapper.select:
SELECT t.TRADE_ID tradeId,/**交易编号**/ null outTradeId, /*外部成交编号*/ NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetAbbr,/**资产简称**/ t.PS ps,/**交易方向**/ t.CCY ccy,/**币种**/
t.TRADE_DATE tradeDate,/**交易日期**/ stl.SETTLE_DATE settleDate,/**结算日期**/ t.PRIN_AMT tradeAmt,/**成交金额**/ t.SHARE_AMT dealNum,/**成交数量**/ stl.MY_ACCT_NO trdMyAcctNo,/**资金账户**/ ttfd.FEE_AMT advFeeOut,/**经手费**/ ttfd2.FEE_AMT commission,/**佣金**/ t.TRADE_AMT settleAmt/**结算金额**/
/*认购*/ t.TRADE_DATE applyDate,/**申请日期**/ stl.SETTLE_DATE subSettleDate,/**结算日期**/ t.TRADE_AMT applyAmt,/**申请金额**/ stl.MY_ACCT_NO subMyAcctNo/**资金账户**/
/*申购*/ t.TRADE_DATE purApplyDate,/**申请日期**/ stl.SETTLE_DATE purSettleDate,/**结算日期**/ t.TRADE_AMT purApplyAmt,/**申请金额**/ stl.MY_ACCT_NO purMyAcctNo/**资金账户**/
/*认购确认*/ t.TRADE_DATE subConfirmDate,/**确认日期**/ t.TRADE_AMT subConfirmAmt,/**确认金额**/ t.SHARE_AMT subConfirmNum,/**确认数量**/ t.INT_AMT raiseInterest,/**募集期利息**/ t.FEE_AMT_UNPAY subFee,/**认购费**/ stl.MY_ACCT_NO subConfirmMyAcctNo/**资金账户**/
/*申购确认*/ t.TRADE_DATE purConfirmDate,/**确认日期**/ t.TRADE_AMT purConfirmAmt,/**确认金额**/ t.SHARE_AMT purConfirmNum,/**确认数量**/ t.UNIT_CPRICE purUnitValue,/**单位净值**/ t.INT_AMT interestIncome,/**利息收入**/ t.FEE_AMT_UNPAY purFee,/**申购费**/ stl.MY_ACCT_NO purConfirmMyAcctNo/**资金账户**/
t.TRADE_DATE redConfirmDate,/**确认日期**/ t.TRADE_AMT redConfirmAmt,/**确认金额**/ t.SHARE_AMT redConfirmNum,/**确认数量**/ t.UNIT_CPRICE redUnitValue,/**单位净值**/ t.FEE_AMT_UNPAY redFee,/**赎回费**/ null arriveDate,/**到账日期**/ stl.MY_ACCT_NO redMyAcctNo/**资金账户**/
FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE in( '06','07') LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_DEAL_ACCOUNTING deal2 ON stl.ORDER_ID = deal2.BUSI_NO LEFT JOIN BOK_BOOKSET bok on (bok.BOOKSET_ID = deal1.BOOKSET_ID) OR (bok.BOOKSET_ID = deal2.BOOKSET_ID) LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd ON ttfd.TRADE_ID = t.TRADE_ID AND ttfd.FEE_TYPE = 'B01' LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd2 ON ttfd2.TRADE_ID = t.TRADE_ID AND ttfd2.FEE_TYPE = 'B08' where t.TRADE_ID = #{tradeId,jdbcType=VARCHAR} and t.BUSI_TYPE IN('06','07') and rownum=1

mapper.delete:
DELETE FROM BOK_DETAIL_ID
WHERE
TRADE_ID = #{tradeId}

	AND BOOKSET_ID = #{booksetId}
